// Fixed lessons and exercises of the eight practice groups (no model call to teach or to build exercises).
// Each lesson reads like a small chapter: `overview` (what the subject is, why Brazilians stumble, a mental model and a
// map of the parts), then rules. Each rule teaches what it is (`when`), how it works (`explain`), why English does it
// that way (`why`), how to build the sentence (`build`), the typical Brazilian traps (`traps`) and real interview
// sentences with their meaning (`examples`). `wrong`/`right` feed the quick "which one is right?" check. Exercises are
// fixed too: `choose` is graded locally; `spot` accepts the listed answers locally and only asks the model when the
// answer is none of them (another valid wording must not be marked wrong). Rule and exercise ids are stored in users'
// data, so existing ids must never change.

const ex = (en, pt) => ({ en, pt });
const trap = (wrong, right, note) => ({ wrong, right, note });
const choose = (id, ruleId, sentence, options, answer, why) => ({ id, ruleId, kind: "choose", sentence, options, answer, why });
const spot = (id, ruleId, sentence, answer, why, accepted) => ({ id, ruleId, kind: "spot", sentence, answer, ...(accepted ? { accepted } : {}), why });

